static void VBox(G g,Vector3 p,Vector3 s,int finish,float glow=0){int n=g.p.Count;surfaceType=0;g.Box(p,s,finish==0?taxiYellow:finish==1?taxiWhite:taxiBlack,glow);if(finish>1)for(int i=n;i<g.mark.Count;i++){var m=g.mark[i];m.x=finish;g.mark[i]=m;}}
static void VTransform(G g,int firstVertex,int firstTriangle,Vector3 origin,Quaternion rotation){for(int i=firstVertex;i<g.p.Count;i++){var v=g.p[i];v.x=-v.x;g.p[i]=origin+rotation*v;}for(int i=firstTriangle;i<g.ids.Count;i+=3){int a=g.ids[i+1];g.ids[i+1]=g.ids[i+2];g.ids[i+2]=a;}}
static void VReverseFace(G g,int firstVertex,int firstTriangle,Vector3 pivot){int end=g.p.Count,ti=g.ids.Count,offset=end-firstVertex;for(int i=firstVertex;i<end;i++){var v=g.p[i]-pivot;g.p.Add(pivot+new Vector3(-v.x,v.y,-v.z));g.uv.Add(g.uv[i]);g.mark.Add(g.mark[i]);}for(int i=firstTriangle;i<ti;i++)g.ids.Add(g.ids[i]+offset);}
static void VStripe(G g,Vector3 a,Vector3 b,bool detail){float length=Vector3.Distance(a,b);int count=Mathf.CeilToInt(length/(detail?.65f:1.5f));var mid=(a+b)*.5f;var rot=Quaternion.LookRotation(b-a);for(int i=0;i<count;i++){var center=Vector3.Lerp(a,b,(i+.5f)/count);int start=g.p.Count;VBox(g,center+Vector3.up*.13f,new Vector3(.32f,.26f,length/count-.01f),i%2==0?0:4);for(int j=start;j<g.p.Count;j++)g.p[j]=center+rot*(g.p[j]-center);}}
