struct VCorner{public Vector3 p;public Vector2 uv;public Vector4 mark;}
static void VClipRoof(G g,int firstVertex,int firstTriangle,bool left){var source=g.p.ToArray();var uvs=g.uv.ToArray();var marks=g.mark.ToArray();var ids=g.ids.Skip(firstTriangle).ToArray();g.p.RemoveRange(firstVertex,g.p.Count-firstVertex);g.uv.RemoveRange(firstVertex,g.uv.Count-firstVertex);g.mark.RemoveRange(firstVertex,g.mark.Count-firstVertex);g.ids.RemoveRange(firstTriangle,g.ids.Count-firstTriangle);Func<VCorner,float> distance=v=>(v.p.x+1)*.970f-(v.p.z+6.5f)*.243f;for(int i=0;i<ids.Length;i+=3){var polygon=new List<VCorner>();for(int j=0;j<3;j++){int k=ids[i+j];polygon.Add(new VCorner{p=source[k],uv=uvs[k],mark=marks[k]});}if(polygon.All(v=>v.p.y>5.20f)){var clipped=new List<VCorner>();for(int j=0;j<polygon.Count;j++){var a=polygon[j];var b=polygon[(j+1)%polygon.Count];float da=distance(a)*(left?1:-1),db=distance(b)*(left?1:-1);if(da>=-.00001f)clipped.Add(a);if((da>=0)!=(db>=0)){float t=da/(da-db);clipped.Add(new VCorner{p=Vector3.Lerp(a.p,b.p,t),uv=Vector2.Lerp(a.uv,b.uv,t),mark=Vector4.Lerp(a.mark,b.mark,t)});}}polygon=clipped;}for(int j=1;j+1<polygon.Count;j++){foreach(var v in new[]{polygon[0],polygon[j],polygon[j+1]}){g.ids.Add(g.p.Count);g.p.Add(v.p);g.uv.Add(v.uv);g.mark.Add(v.mark);}}}}static void VImport(G g,Mesh mesh,Vector3 offset,Func<Vector3,bool> filter=null){var v=mesh.vertices;var uv=mesh.uv;var marks=new List<Vector4>();mesh.GetUVs(3,marks);var tri=mesh.triangles;for(int i=0;i<tri.Length;i+=3){if(filter!=null&&(!filter(v[tri[i]])||!filter(v[tri[i+1]])||!filter(v[tri[i+2]])))continue;int first=g.p.Count;for(int j=0;j<3;j++){int index=tri[i+j];g.p.Add(v[index]+offset);g.uv.Add(uv[index]);g.mark.Add(marks[index]);g.ids.Add(first+j);}}}
public static Mesh[] BuildTaxiV(bool detail){var existing=BuildTaxiStandMeshes(detail);atlas=new Texture2D(2,2);var mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");atlas.LoadImage(File.ReadAllBytes(AssetDatabase.GetAssetPath(mat.GetTexture("_BaseMap"))));taxiFarDetail=!detail;var roof=new G();var signs=new G();var floor=new G();var booth=new G();
VWing(roof,signs,floor,new Vector3(-1,0,-6.5f),new Vector3(12,0,-6),new Vector3(-.0384f,0,.9993f),3,1,detail);
VWing(roof,signs,floor,new Vector3(-1,0,-6.5f),new Vector3(-12,0,0),new Vector3(.5087f,0,.8609f),2,4,detail);
foreach(float x in new[]{-3.8f,-.4f}){VBox(roof,new Vector3(x,2.68f,-7),new Vector3(.22f,5.36f,.22f),4);VBox(roof,new Vector3(x,.11f,-7),new Vector3(.56f,.22f,.56f),5);VBox(roof,new Vector3(x,.75f,-7),new Vector3(.24f,.25f,.24f),0);}
VImport(booth,existing[1],new Vector3(3.85f,0,-3.6f));
VImport(signs,existing[2],new Vector3(4.9f,0,-4.0f),p=>p.y<4.0f);
VBox(floor,new Vector3(12,.13f,3.1f),new Vector3(1.4f,.26f,2.6f),5);VStripe(floor,new Vector3(11.35f,0,1.8f),new Vector3(12.75f,0,1.8f),detail);VStripe(floor,new Vector3(11.35f,0,4.4f),new Vector3(12.75f,0,4.4f),detail);
// Large open court, clipped to the corner plot; original asphalt region in the existing atlas.
var polygon=new[]{new Vector3(-14,0,-3),new Vector3(-5,0,-9),new Vector3(13.7f,0,-9),new Vector3(13.7f,0,8),new Vector3(10,0,10.5f),new Vector3(-10.5f,0,10.5f),new Vector3(-14,0,7)};
Vector3 center=new Vector3(0,.018f,1);surfaceType=2;for(int i=0;i<polygon.Length;i++){var a=polygon[i]+Vector3.up*.018f;var b=polygon[(i+1)%polygon.Length]+Vector3.up*.018f;Func<Vector3,Vector2> uv=p=>new Vector2(.20f+(p.x+14)/28*.23f,.28f+(p.z+9)/20*.20f);floor.Tri(center,b,a,uv(center),uv(b),uv(a));}
var result=new List<Mesh>();foreach(var p in new[]{new KeyValuePair<string,G>("Canopy",roof),new KeyValuePair<string,G>("Signs",signs),new KeyValuePair<string,G>("Booth",booth),new KeyValuePair<string,G>("Court",floor)}){var m=new Mesh{name="Taxi Open V "+p.Key+(detail?" Near":" Far")};WriteG(m,p.Value);result.Add(m);}foreach(var m in existing)UnityEngine.Object.DestroyImmediate(m);UnityEngine.Object.DestroyImmediate(atlas);surfaceType=0;return result.ToArray();}
